package com.dispatchpro.driver;
import android.view.KeyEvent;
import android.os.SystemClock;
import org.json.JSONObject;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.Robolectric;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import org.robolectric.Shadows;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=34)
public class RadioRuntimeTest {
 RadioService service;RadioExternalKeys keys;
 @Before public void before(){service=Robolectric.buildService(RadioService.class).get();service.getSharedPreferences("radio-external",0).edit().clear().commit();keys=new RadioExternalKeys(service);service.keys=keys;service.operational=true;service.microphoneReady=true;}
 @After public void after(){keys.close();}
 @Test public void selectingDriverStopsRadioAndDoesNotConsumeItsEvents()throws Exception{
  assign();long down=SystemClock.uptimeMillis();assertTrue(keys.key(key(KeyEvent.ACTION_DOWN,0,down),"Activity"));assertTrue(keys.hold.pressed());
  keys.configure(new JSONObject().put("action","owner").put("owner","driver"));assertFalse(keys.hold.pressed());
  assertFalse(keys.key(key(KeyEvent.ACTION_DOWN,0,SystemClock.uptimeMillis()),"AccessibilityService"));assertEquals("driver",keys.info().getString("owner"));
  keys.configure(new JSONObject().put("action","owner").put("owner","radio"));assertTrue(keys.key(key(KeyEvent.ACTION_DOWN,0,SystemClock.uptimeMillis()),"Activity"));
 }
 @Test public void volumeAndTelephoneKeysKeepSystemBehavior()throws Exception{
  keys.configure(new JSONObject().put("action","learn"));for(int code:new int[]{24,25,164,5,6})assertFalse(keys.key(new KeyEvent(KeyEvent.ACTION_DOWN,code),"Activity"));assertNull(keys.candidate);
 }
 KeyEvent key(int action,int repeat,long down){return new KeyEvent(down,SystemClock.uptimeMillis(),action,KeyEvent.KEYCODE_HEADSETHOOK,repeat);}
 void assign()throws Exception{keys.configure(new JSONObject().put("action","learn"));long down=SystemClock.uptimeMillis();assertTrue(keys.key(key(KeyEvent.ACTION_DOWN,0,down),"Activity"));SystemClock.sleep(200);assertTrue(keys.key(key(KeyEvent.ACTION_UP,0,down),"Activity"));keys.configure(new JSONObject().put("action","save"));}
 @Test public void learnsRealPairPersistsChannelAndHasNoDefault()throws Exception{assertEquals(0,keys.info().getInt("keyCode"));assign();keys.configure(new JSONObject().put("action","channel").put("channel","private"));RadioExternalKeys restored=new RadioExternalKeys(service);try{assertEquals(KeyEvent.KEYCODE_HEADSETHOOK,restored.info().getInt("keyCode"));assertEquals("private",restored.info().getString("channel"));String name=restored.info().getString("keyName");assertTrue(name.equals("KEYCODE_HEADSETHOOK")||name.equals("79"));}finally{restored.close();}}
 @Test public void repeatsAndStaleUpCannotReleaseNextPress()throws Exception{assign();long first=SystemClock.uptimeMillis();keys.key(key(KeyEvent.ACTION_DOWN,0,first),"MediaSession");assertTrue(keys.hold.pressed());keys.key(key(KeyEvent.ACTION_DOWN,1,first),"MediaSession");keys.key(key(KeyEvent.ACTION_UP,0,first),"MediaSession");assertFalse(keys.hold.pressed());SystemClock.sleep(2);long next=SystemClock.uptimeMillis();keys.key(key(KeyEvent.ACTION_DOWN,0,next),"MediaSession");keys.key(key(KeyEvent.ACTION_UP,0,first),"MediaSession");assertTrue(keys.hold.pressed());keys.key(key(KeyEvent.ACTION_UP,0,next),"MediaSession");assertFalse(keys.hold.pressed());}
 @Test public void disconnectAndTimeoutReleaseAndDisabledGpsCannotTransmit()throws Exception{assign();long down=SystemClock.uptimeMillis();keys.key(key(KeyEvent.ACTION_DOWN,0,down),"Activity");keys.onInputDeviceRemoved(-1);assertFalse(keys.hold.pressed());down=SystemClock.uptimeMillis();keys.key(key(KeyEvent.ACTION_DOWN,0,down),"Activity");keys.expire.run();assertFalse(keys.hold.pressed());service.operational=false;assertFalse(keys.key(key(KeyEvent.ACTION_DOWN,0,SystemClock.uptimeMillis()),"Activity"));assertFalse(keys.hold.pressed());}
 @Test public void testModeNeverTransmitsAndClearRemovesMapping()throws Exception{assign();keys.configure(new JSONObject().put("action","test"));long down=SystemClock.uptimeMillis();keys.key(key(KeyEvent.ACTION_DOWN,0,down),"Activity");assertFalse(keys.hold.pressed());keys.key(key(KeyEvent.ACTION_UP,0,down),"Activity");assertTrue(keys.info().getBoolean("released"));keys.configure(new JSONObject().put("action","clear"));assertEquals(0,keys.info().getInt("keyCode"));}
 @Test public void mediaHeadsetDisconnectReleasesEvenWhenKeyEventHasNoPhysicalDeviceId()throws Exception{assign();long down=SystemClock.uptimeMillis();keys.key(key(KeyEvent.ACTION_DOWN,0,down),"MediaSession");assertTrue(keys.hold.pressed());keys.audioDevices.onAudioDevicesRemoved(new android.media.AudioDeviceInfo[]{null});assertFalse(keys.hold.pressed());}
 @Test public void protectedKeysAndClickOnlyCannotBeSaved()throws Exception{keys.configure(new JSONObject().put("action","learn"));assertFalse(keys.key(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_POWER),"Activity"));long down=SystemClock.uptimeMillis();keys.key(key(KeyEvent.ACTION_DOWN,0,down),"Activity");keys.key(key(KeyEvent.ACTION_UP,0,down),"Activity");try{keys.configure(new JSONObject().put("action","save"));fail("Click-only input must be rejected");}catch(org.json.JSONException expected){}assertEquals(0,keys.store.getInt("keyCode",0));}
 @Test public void gpsRequiresActualServerAcknowledgement(){assertFalse(RadioPolicy.operational(false,true,true,true));assertTrue(RadioPolicy.operational(true,false,true,true));assertTrue(RadioPolicy.operational(true,true,false,true));assertTrue(RadioPolicy.operational(true,true,true,false));assertTrue(RadioPolicy.operational(true,true,true,true));assertEquals("yellow",RadioPolicy.tracking(true,false,100000,0));assertEquals("green",RadioPolicy.tracking(true,false,100000,99000));assertEquals("yellow",RadioPolicy.tracking(true,false,200000,99000));assertEquals("red",RadioPolicy.tracking(true,true,100000,99000));assertEquals("red",RadioPolicy.tracking(false,false,100000,99000));}
 @Test public void disabledGpsKeepsRadioWhileVisibleReturnRestoresLocation(){Shadows.shadowOf(org.robolectric.RuntimeEnvironment.getApplication()).grantPermissions(android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION,android.Manifest.permission.RECORD_AUDIO);var controller=Robolectric.buildService(RadioService.class).create();RadioService runtime=controller.get();try{var screen=Robolectric.buildActivity(RadioActivity.class).get();screen.resumed=true;runtime.activity=screen;var lm=runtime.getSystemService(android.location.LocationManager.class);Shadows.shadowOf(lm).setLocationEnabled(true);runtime.authenticated=true;runtime.duty(true);assertTrue(runtime.operational);assertTrue(runtime.foregroundStarted);assertNull(runtime.cpu);RadioEngine engine=runtime.engine;screen.resumed=false;runtime.changed();assertNotNull(runtime.cpu);screen.resumed=true;runtime.changed();assertNull(runtime.cpu);screen.resumed=false;runtime.changed();assertNotNull(runtime.cpu);Shadows.shadowOf(lm).setLocationEnabled(false);runtime.changed();assertTrue(runtime.operational);assertTrue(runtime.foregroundStarted);assertFalse(runtime.locationRunning);assertNotNull(runtime.cpu);assertFalse(runtime.keys.hold.pressed());screen.resumed=true;Shadows.shadowOf(lm).setLocationEnabled(true);runtime.changed();assertTrue(runtime.operational);assertSame(engine,runtime.engine);}finally{controller.destroy();}}
 @Test public void activityRecreationUsesSameServiceEngine(){var controller=Robolectric.buildService(RadioService.class).create();RadioService runtime=controller.get();try{Shadows.shadowOf(org.robolectric.RuntimeEnvironment.getApplication()).setComponentNameAndServiceForBindService(new android.content.ComponentName(runtime,RadioService.class),runtime.binder);RadioEngine engine=runtime.engine;var a=Robolectric.buildActivity(RadioActivity.class).create().start().resume();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertSame(runtime,a.get().radio);runtime.detached(a.get());a.pause().stop().destroy();var b=Robolectric.buildActivity(RadioActivity.class).create().start().resume();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertSame(engine,runtime.engine);assertSame(engine.web,b.get().root.getChildAt(0));b.pause().stop().destroy();}finally{controller.destroy();}}
 @Test public void restartRestoresReceiveWithoutMicrophoneOrLocation(){var controller=Robolectric.buildService(RadioService.class).create();RadioService runtime=controller.get();try{runtime.getSharedPreferences("radio-runtime",0).edit().putBoolean("requested",true).commit();runtime.requested=true;assertEquals(android.app.Service.START_STICKY,runtime.onStartCommand(null,0,1));runtime.authenticated=true;runtime.changed();assertTrue(runtime.operational);assertTrue(runtime.foregroundStarted);assertFalse(runtime.microphoneReady);assertFalse(runtime.locationRunning);assertNotNull(runtime.cpu);}finally{controller.destroy();}}
 @Test public void recentRemovalAndThirtyMinutesRetainSameReceiveEngine(){var controller=Robolectric.buildService(RadioService.class).create();RadioService runtime=controller.get();try{runtime.requested=true;runtime.restoreReceive=true;runtime.startReceivingForeground();runtime.authenticated=true;runtime.changed();RadioEngine same=runtime.engine;runtime.onTaskRemoved(new android.content.Intent());for(int minutes:new int[]{5,10,15}){Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMinutes(minutes));assertTrue(runtime.operational);assertSame(same,runtime.engine);assertTrue(runtime.cpu.isHeld());assertFalse(runtime.microphoneReady);}}finally{controller.destroy();}}
 @Test public void driverReceiveServiceSurvivesMicrophoneReleaseWithoutGps(){var host=Robolectric.buildActivity(MainActivity.class).get();DriverForegroundService.receiving(host,true);var controller=Robolectric.buildService(DriverForegroundService.class).create();var runtime=controller.get();try{runtime.getSharedPreferences("driver-duty",0).edit().putBoolean("online",false).commit();runtime.onStartCommand(new android.content.Intent(),0,1);assertTrue(DriverForegroundService.running);assertTrue(DriverForegroundService.receivingReady());assertEquals(android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK,runtime.getForegroundServiceType());DriverForegroundService.releaseMicrophone(host);runtime.onStartCommand(new android.content.Intent(),0,2);assertTrue(DriverForegroundService.running);assertFalse(DriverForegroundService.microphoneReady());}finally{controller.destroy();}}
}
